// EXI Engine Adapter for V2G Message Encoding/Decoding
//
// This adapter bridges TTCN-3 test cases with the pre-encoded EXI payload library
// generated by exi_harvester.py from iso15118-master.
//
// Payload library resolution:
//   1. EXI_PAYLOAD_LIBRARY env var (absolute path, highest priority)
//   2. ../../exi_payload_library.json (relative to build/bin/ where TestExecutable runs)
//   3. agent/test_code/examples/demo/exi_payload_library.json (relative to repo root)
//
// SessionID patching: Four messages (session_setup/stop req/res) store
// "0000000000000000" as a placeholder. encode(key, session_id) replaces it.

#ifndef EXI_CODEC_ADAPTER_HH
#define EXI_CODEC_ADAPTER_HH

#include <vector>
#include <cstdint>
#include <string>
#include <map>

struct ExiCodecOptions {
    uint8_t value_table_present;
    uint8_t self_contained_present;
    uint8_t element_present;
    uint8_t schema_aware;
    uint8_t fidelity_options;
};

struct ExiCodecResult {
    bool success;
    std::string error_message;
    int bytes_consumed;
};

struct PayloadEntry {
    std::string wire_hex;        // V2GTP header + EXI payload (hex string)
    std::string exi_payload_hex;   // EXI only (hex string)
    std::string namespace_;        // e.g. "urn:iso:15118:2:2013:MsgDef"
    std::string payload_type;     // e.g. "0x8001"
    bool is_dynamic;              // true if SessionID patching is needed
    std::vector<std::string> dynamic_fields; // e.g. ["SessionID"]
};

class ExiCodecAdapter {
public:
    static ExiCodecAdapter& instance();

    // Initialize: tries to load payload library from standard paths.
    bool initialize(bool schema_aware = false);

    // Load payload library from explicit path.
    bool load_library(const std::string& path);

    // Encode: look up pre-encoded wire bytes by message key.
    // session_id non-empty -> patch SessionID in the wire bytes.
    ExiCodecResult encode(const std::string& message_key,
                          const std::string& session_id,
                          std::vector<uint8_t>& wire_output);

    // Convenience overload: accepts const char* to avoid std::string ABI issues
    // when linked against TITAN's legacy-ABI-compiled code.
    void encode(const char* message_key, const std::string& session_id,
                std::vector<uint8_t>& wire_output);

    // Decode: pass-through stub (TTCN-3 test case handles validation).
    ExiCodecResult decode(const std::vector<uint8_t>& exi_data,
                          std::vector<uint8_t>& xml_output);

    // Raw accessors
    std::vector<uint8_t> get_wire_bytes(const std::string& key);
    std::vector<uint8_t> get_exi_bytes(const std::string& key);
    bool has_key(const std::string& key) const;
    std::vector<std::string> available_keys() const;

    // Metadata
    std::string library_path() const { return library_path_; }
    int library_count() const { return static_cast<int>(payloads_.size()); }
    bool library_loaded() const { return library_loaded_; }

    void set_options(const ExiCodecOptions& options);
    std::string get_last_error() const { return last_error_; }

private:
    ExiCodecAdapter();
    ExiCodecAdapter(const ExiCodecAdapter&) = delete;
    ExiCodecAdapter& operator=(const ExiCodecAdapter&) = delete;

    std::vector<uint8_t> hex_to_bytes(const std::string& hex);
    std::vector<uint8_t> patch_session_id(const std::vector<uint8_t>& wire_bytes,
                                           const std::string& new_session_id) const;

    bool library_loaded_;
    std::string library_path_;
    std::map<std::string, PayloadEntry> payloads_;
    bool initialized_;
    std::string last_error_;
    ExiCodecOptions options_;
};

#endif // EXI_CODEC_ADAPTER_HH
